@Ignore
// DRILL-2092: count distinct, non distinct aggregate with group-by
@Test
public void testDrill2092() throws Exception {
    String query = "select a1, b1, count(distinct c1) as dist1, \n" + "sum(c1) as sum1, count(c1) as cnt1, count(*) as cnt \n" + "from cp.`agg/bugs/drill2092/input.json` \n" + "group by a1, b1 order by a1, b1";
    String baselineQuery = "select case when columns[0]='null' then cast(null as bigint) else cast(columns[0] as bigint) end as a1, \n" + "case when columns[1]='null' then cast(null as bigint) else cast(columns[1] as bigint) end as b1, \n" + "case when columns[2]='null' then cast(null as bigint) else cast(columns[2] as bigint) end as dist1, \n" + "case when columns[3]='null' then cast(null as bigint) else cast(columns[3] as bigint) end as sum1, \n" + "case when columns[4]='null' then cast(null as bigint) else cast(columns[4] as bigint) end as cnt1, \n" + "case when columns[5]='null' then cast(null as bigint) else cast(columns[5] as bigint) end as cnt \n" + "from cp.`agg/bugs/drill2092/result.tsv`";
    // NOTE: this type of query gets rewritten by Calcite into an inner join of subqueries, so
    // we need to test with both hash join and merge join
    testBuilder().sqlQuery(query).ordered().optionSettingQueriesForTestQuery("alter system set `planner.enable_hashjoin` = true").sqlBaselineQuery(baselineQuery).build().run();
    testBuilder().sqlQuery(query).ordered().optionSettingQueriesForTestQuery("alter system set `planner.enable_hashjoin` = false").sqlBaselineQuery(baselineQuery).build().run();
}

// DRILL-2170: Subquery has group-by, order-by on aggregate function and limit
@Test
