        test("USE cp");
        queryViewHelper(String.format("SELECT * FROM %s.`%s` ORDER BY `employeeid` DESC LIMIT 1", "dfs_test.tmp", viewName), baselineColumns, baselineValues);
    } finally {
        dropViewHelper(TEMP_SCHEMA, viewName, TEMP_SCHEMA);
    }
}

