@Test
public void testPlanVerifier() throws Exception {
    String query = "select * from cp.`tpch/lineitem.parquet`";
    String expectedPattern = "selectionRoot=classpath:/tpch/lineitem.parquet, numFiles=[1-9]+, ";
    String excludedPattern = "part.parquet";
    testPlanMatchingPatterns(query, new String[] { expectedPattern }, new String[] { excludedPattern });
    testPlanMatchingPatterns(query, null, new String[] { excludedPattern });
    testPlanMatchingPatterns(query, new String[] { expectedPattern }, new String[] {});
    try {
        testPlanMatchingPatterns(query, new String[] { expectedPattern }, new String[] { expectedPattern });
    } catch (AssertionError ex) {
        assertEquals(ex.getMessage(), UNEXPECTED_FOUND + expectedPattern);
    }
    try {
        testPlanMatchingPatterns(query, new String[] { excludedPattern }, new String[] { excludedPattern });
    } catch (AssertionError ex) {
        assertEquals(ex.getMessage(), EXPECTED_NOT_FOUND + excludedPattern);
    }
}

