    String[] csvQueries = { //        format("select columns from %s ('TeXT')", csvTableName),
    //        format("select columns from %s('TeXT')", csvTableName),
    format("select columns from table(%s ('TeXT'))", csvTableName), format("select columns from table(%s (type => 'TeXT'))", csvTableName) //        format("select columns from %s (type => 'TeXT')", csvTableName)
    };
    for (String csvQuery : csvQueries) {
        testWithResult(csvQuery, listOf("a,b"), listOf("c|d"));
    }
    // the drill config file binds .csv to "," delimited
    testWithResult(format("select columns from %s", csvTableName), listOf("a", "b"), listOf("c|d"));
    // setting the delimiter
    testWithResult(format("select columns from table(%s (type => 'TeXT', fieldDelimiter => ','))", csvTableName), listOf("a", "b"), listOf("c|d"));
