@Test(expected = SQLConversionOverflowException.class)
public void test_getByte_on_SMALLINT_thatOverflows_rejectsIt() throws InvalidAccessException {
    final SqlAccessor uut = new TypeConvertingSqlAccessor(new SmallIntStubAccessor((short) 128));
    try {
        uut.getByte(0);
    } catch (Throwable e) {
        // Expect the too-big source value in error message:
        assertThat(e.getMessage(), containsString("128"));
        // Probably expect the method name:
        assertThat(e.getMessage(), containsString("getByte"));
        // Expect something about source type (original SQL type and default Java
        // type, currently).
        assertThat(e.getMessage(), allOf(containsString("short"), containsString("SMALLINT")));
        throw e;
    }
}

