    } catch (final SQLFeatureNotSupportedException e) {
        assertThat("Check whether params.-unsupported wording changed or checks changed.", e.toString(), PARAMETERS_NOT_SUPPORTED_MSG_MATCHER);
        throw e;
    }
}

