/**
 * Basic test that column DATA_TYPE is integer type codes (not strings such
 * as "VARCHAR" or "INTEGER").
 */
@SuppressWarnings("unchecked")
@Test
public void testColumn_DATA_TYPE_isInteger() throws Exception {
    // Get metadata for some column(s).
    final ResultSet columns = dbMetadata.getColumns(null, null, null, null);
    assertTrue("DatabaseMetaData.getColumns(...) returned no rows", columns.next());
    do {
        // DATA_TYPE should be INTEGER, so getInt( "DATA_TYPE" ) should succeed:
        final int typeCode1 = columns.getInt("DATA_TYPE");
        // DATA_TYPE should be at ordinal position 5 (seemingly):
        assertThat("Column 5's label", columns.getMetaData().getColumnLabel(5), equalTo("DATA_TYPE"));
        // Also, getInt( 5 ) should succeed and return the same type code as above:
        final int typeCode2 = columns.getInt(5);
        assertThat("getInt( 5 ) (expected to be same as getInt( \"DATA_TYPE\" ))", typeCode2, equalTo(typeCode1));
        // Type code should be one of java.sql.Types.*:
        assertThat(typeCode1, // List is from java.sql.Types
        anyOf(equalTo(Types.ARRAY), equalTo(Types.BIGINT), equalTo(Types.BINARY), equalTo(Types.BIT), equalTo(Types.BLOB), equalTo(Types.BOOLEAN), equalTo(Types.CHAR), equalTo(Types.CLOB), equalTo(Types.DATALINK), equalTo(Types.DATE), equalTo(Types.DECIMAL), equalTo(Types.DISTINCT), equalTo(Types.DOUBLE), equalTo(Types.FLOAT), equalTo(Types.INTEGER), equalTo(Types.JAVA_OBJECT), equalTo(Types.LONGNVARCHAR), equalTo(Types.LONGVARBINARY), equalTo(Types.LONGVARCHAR), equalTo(Types.NCHAR), equalTo(Types.NCLOB), // TODO:  Resolve:  Is it not clear whether Types.NULL can re-
        // present a type (e.g., the type of NULL), or whether a column
        // can ever have that type, and therefore whether Types.NULL
        // can appear.  Currently, exclude NULL so we'll notice if it
        // does appear:
        // No equalTo( Types.NULL ).
        equalTo(Types.NUMERIC), equalTo(Types.NVARCHAR), equalTo(Types.OTHER), equalTo(Types.REAL), equalTo(Types.REF), equalTo(Types.ROWID), equalTo(Types.SMALLINT), equalTo(Types.SQLXML), equalTo(Types.STRUCT), equalTo(Types.TIME), equalTo(Types.TIMESTAMP), equalTo(Types.TINYINT), equalTo(Types.VARBINARY), equalTo(Types.VARCHAR)));
    } while (columns.next());
}

