@Test
public void testIntervalInViewDoesntCrashInfoSchema() throws Exception {
    final Statement stmt = connection.createStatement();
    ResultSet util;
    // Create a view using an INTERVAL type:
    util = stmt.executeQuery("USE dfs_test.tmp");
    assertTrue(util.next());
    assertTrue("Error setting schema to dfs_test.tmp: " + util.getString(2), util.getBoolean(1));
    util = stmt.executeQuery("CREATE OR REPLACE VIEW " + VIEW_NAME + " AS " + "\n  SELECT CAST( NULL AS INTERVAL HOUR(4) TO MINUTE ) AS optINTERVAL_HM " + "\n  FROM INFORMATION_SCHEMA.CATALOGS " + "\n  LIMIT 1 ");
    assertTrue(util.next());
    assertTrue("Error creating temporary test-columns view " + VIEW_NAME + ": " + util.getString(2), util.getBoolean(1));
    // Test whether query INFORMATION_SCHEMA.COLUMNS works (doesn't crash):
    util = stmt.executeQuery("SELECT * FROM INFORMATION_SCHEMA.COLUMNS");
    assertTrue(util.next());
    // Clean up the test view:
    util = connection.createStatement().executeQuery("DROP VIEW " + VIEW_NAME);
    assertTrue(util.next());
    assertTrue("Error dropping temporary test-columns view " + VIEW_NAME + ": " + util.getString(2), util.getBoolean(1));
}

